import functools
def tilings(n, m):
    full = (1 << n * m) - 1
    @functools.lru_cache(None)
    def go(mask):
        if mask == full: return 1
        cell = next(i for i in range(n * m) if not mask >> i & 1); r, c = divmod(cell, m); total = 0
        if c + 1 < m and not mask >> (cell + 1) & 1: total += go(mask | 1 << cell | 1 << (cell + 1))
        if r + 1 < n: total += go(mask | 1 << cell | 1 << (cell + m))
        return total
    return go(0)
def profile(n, m):
    @functools.lru_cache(None)
    def col(j, mask):
        if j == m: return 1 if mask == 0 else 0
        out = {}
        def fill(i, cur, nxt):
            if i == n: out[nxt] = out.get(nxt, 0) + 1; return
            if cur >> i & 1: fill(i + 1, cur, nxt); return
            fill(i + 1, cur | 1 << i, nxt | 1 << i)
            if i + 1 < n and not cur >> (i + 1) & 1: fill(i + 2, cur | 3 << i, nxt)
        fill(0, mask, 0)
        return sum(k * col(j + 1, nxt) for nxt, k in out.items())
    return col(0, 0)
result = tilings(2, 3)

